(()=>{'use strict';
const root=document.getElementById('content'),select=document.getElementById('level');let level='A2',screen='home';
const buttons=[['verbs','Глаголы','Формы, времена и любимая практика','Α'],['grammar','Грамматика','Понятные объяснения и примеры','ο'],['lexicon','Лексика и фразы','Слова и выражения в ситуациях','α'],['training','Тренировка','Приложение подбирает задания','✓'],['practice','Практика','Выбирай тему и упражнение сама','✎'],['exam','Экзамен','Подготовка к выбранному уровню','◉']];
const tile=(id,title,sub,icon)=>`<button class="tile" data-screen="${id}"><span class="icon">${icon}</span><strong>${title}</strong><span>${sub}</span></button>`;
const context=label=>`<div class="context"><button data-screen="home">Главная</button> → ${label} · ${level}</div>`;
const placeholder=()=>level==='A2'?'':`<div class="note">${level}: здесь показана структура будущего раздела. Полный материал этого уровня ещё предстоит подготовить.</div>`;
function home(){return `<div class="intro"><span class="eyebrow">ГРЕЧЕСКИЙ ДЛЯ ЖИЗНИ</span><h1>Греческий язык — в своём темпе</h1><p class="muted">Изучай, тренируйся и готовься к экзамену. Начинай с уровня, который нужен тебе.</p></div><section class="hero"><div><span class="status">Твой уровень · ${level}</span><h2>Что будем изучать сегодня?</h2><p class="muted">Выбери раздел или начни короткую тренировку.</p></div><button class="cta" data-screen="training">Начать тренировку →</button></section><h2>Все разделы</h2><div class="grid">${buttons.map(v=>tile(...v)).join('')}</div>`}
function verbs(){return `${context('Глаголы')}<span class="eyebrow">ТВОЙ СПРАВОЧНИК</span><h1>Греческие глаголы</h1><p class="muted">Формы, времена, карточки и самостоятельная практика.</p><div class="note">Это экран перехода в прототипе. Существующий раздел глаголов сохраняет свой дизайн и механику.</div><div class="card"><h2>Например: γράφω — писать</h2><div class="example-list"><div>γράφω<br><small>настоящее</small></div><div>έγραψα<br><small>прошедшее</small></div><div>θα γράψω<br><small>будущее</small></div></div><div class="subnav"><button class="choice" data-screen="grammar">Как выбрать время? →</button><button class="choice" data-screen="practice">Перейти к практике →</button></div></div>`}
function existing(view,title,desc){if(level!=='A2')return `${context(title)}<span class="eyebrow">${level} · ${title}</span><h1>${title}</h1><p class="muted">${desc}</p>${placeholder()}<div class="subnav"><button class="choice" data-screen="home">К разделам</button><button class="choice" data-screen="exam">Подготовка к ${level}</button></div>`;return `${context(title)}<span class="eyebrow">A2 · ${title}</span><h1>${title}</h1><p class="muted">${desc}</p><div class="subnav"><button class="choice" data-screen="grammar">Грамматика</button><button class="choice" data-screen="training">Тренировка</button><button class="choice" data-screen="practice">Практика</button><button class="choice" data-screen="exam">К экзамену A2</button></div><div class="iframe-wrap"><iframe title="Существующий прототип A2 — ${title}" src="../a2-cards/?view=${view}"></iframe></div>`}
function lexicon(){return `${context('Лексика')}<span class="eyebrow">МАТЕРИАЛЫ · ${level}</span><h1>Лексика и фразы</h1><p class="muted">Слова и выражения в знакомых ситуациях.</p>${placeholder()}<div class="grid">${['В кафе','Город и транспорт','Путешествия'].map(x=>tile('lex-example',x,'Посмотреть пример','α')).join('')}</div>`}
function lexExample(){return `${context('Лексика → В кафе')}<span class="eyebrow">ПРИМЕР КАРТОЧКИ</span><h1>В кафе</h1><div class="card"><h2>ο καφές — кофе</h2><div class="greek" lang="el">Θα ήθελα έναν καφέ, παρακαλώ.</div><p>Я бы хотела кофе, пожалуйста.</p><div class="subnav"><button class="choice" data-screen="grammar">Почему έναν? → Грамматика</button><button class="choice" data-screen="practice">Потренировать</button></div></div>`}
function exam(){return `${context('Экзамен')}<span class="eyebrow">ПОДГОТОВКА К ${level}</span><h1>Подготовка к ${level}</h1><p class="muted">Выбери навык для тренировки.</p>${placeholder()}<div class="grid">${[['exam-reading','Чтение','Объявления, сообщения и тексты','▤'],['exam-listening','Слушание','Диалоги и сообщения','♫'],['exam-writing','Письмо','Письма и объявления','✎'],['exam-speaking','Говорение','Ответы и описание картинки','◌'],['lexicon','Темы и фразы','Лексика по ситуациям','α'],['verbs','Глаголы','Формы и употребление','Α']].map(v=>tile(...v)).join('')}</div><div class="card"><h2>Тренировочный экзамен</h2><p class="muted">Полный пробный экзамен — следующий этап разработки.</p></div>`}
const examLabels={'exam-reading':'Чтение','exam-listening':'Слушание','exam-writing':'Письмо','exam-speaking':'Говорение'};
function examSkill(){return `${context('Экзамен → '+examLabels[screen])}<span class="eyebrow">ПОДГОТОВКА К ${level}</span><h1>${examLabels[screen]}</h1><p class="muted">Здесь появятся задания по выбранному навыку.</p><div class="card"><h2>Нужна подсказка?</h2><p>Можно открыть правило или повторить нужные слова и вернуться к заданию.</p><div class="subnav"><button class="choice" data-screen="grammar">Открыть грамматику</button><button class="choice" data-screen="lexicon">Посмотреть слова</button><button class="choice" data-screen="exam">К навыкам экзамена</button></div></div>`}
function render(){root.classList.toggle('green',['grammar','training','practice'].includes(screen));select.value=level;const navScreen=screen==='lex-example'?'lexicon':screen.startsWith('exam-')?'exam':screen;document.querySelectorAll('nav button').forEach(b=>{b.dataset.screen===navScreen?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')});root.innerHTML=screen==='home'?home():screen==='verbs'?verbs():screen==='grammar'?existing('grammar','Грамматика','Разбирай правила и сразу пробуй применять их.'):screen==='training'?existing('training','Тренировка','Короткая последовательность заданий с обратной связью.'):screen==='practice'?existing('practice','Практика','Выбирай тему, формат и свой темп.'):screen==='lexicon'?lexicon():screen==='lex-example'?lexExample():screen==='exam'?exam():examSkill();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-screen]');if(!b)return;screen=b.dataset.screen;render()});select.addEventListener('change',()=>{level=select.value;render()});render();
})();
